insert into public.projects
  (key, name, description, quarter_id, phase, rag, status_text, status_updated_at,
   srb_merge, api_spec_merge, commit_pitch, dev_complete, release)
values
  ('CW-1042', 'Telum II accelerator enablement', 'Enable the on-chip AI accelerator in Telum II for production workloads: firmware exposure, kernel driver support and the runtime hooks used by inference libraries.', '4Q26', 'pipeline', 'green', 'Code merged. Promotion through pipeline stages underway; verification starts on promotion.', timestamptz '2026-09-22T15:00:00Z' - interval '4 days', '2026-08-20', '2026-09-03', '2026-09-15', '2026-11-12', '2026-12-14'),
  ('CW-1067', 'Power11 firmware GA', 'General availability of the Power11 firmware stack across all supported chassis, closing the remaining beta defects and publishing the upgrade path from Power10.', '4Q26', 'released', 'green', 'GA on 14 Dec 2026. In sustainment; remaining work is defect intake.', timestamptz '2026-09-22T15:00:00Z' - interval '8 days', '2026-08-24', '2026-09-03', '2026-09-07', '2026-11-12', '2026-12-14'),
  ('CW-1088', 'LinuxONE 5 capacity on demand', 'Temporary and permanent capacity activation for LinuxONE 5 through the fleet portal, with billing hooks and automated deactivation.', '4Q26', 'test', 'green', 'In verification. Exit criteria tracking to release on 14 Dec 2026.', timestamptz '2026-09-22T15:00:00Z' - interval '8 days', '2026-08-24', '2026-09-02', '2026-09-08', '2026-11-12', '2026-12-14'),
  ('CW-1103', 'Spyre AI accelerator integration', 'Integrate Spyre accelerator cards into the compute fleet: PCIe enumeration, kernel driver, scheduling primitives and telemetry.', '4Q26', 'dev', 'yellow', 'At risk: Spyre firmware drop slipped two weeks, dev complete date under review. Build in progress across AI Infra and Kernel. Dev complete targeted 13 Nov 2026.', timestamptz '2026-09-22T15:00:00Z' - interval '5 days', '2026-08-21', '2026-08-31', '2026-09-10', '2026-11-13', '2026-12-14'),
  ('CW-1115', 'Bare metal provisioning API v3', 'Third-generation provisioning API with declarative host profiles, an async job model and parity across Z, Power and x86 pools.', '4Q26', 'test', 'green', 'In verification. Exit criteria tracking to release on 14 Dec 2026.', timestamptz '2026-09-22T15:00:00Z' - interval '2 days', '2026-08-18', '2026-09-04', '2026-09-10', '2026-11-13', '2026-12-14'),
  ('CW-1121', 'Confidential compute attestation', 'Remote attestation service for confidential VMs, producing signed evidence that customer key brokers can consume.', '4Q26', 'dev', 'green', 'Build in progress across Security. Dev complete targeted 14 Nov 2026.', timestamptz '2026-09-22T15:00:00Z' - interval '2 days', '2026-08-18', '2026-09-08', '2026-09-11', '2026-11-14', '2026-12-14'),
  ('CW-1130', 'Fleet firmware auto-patching', 'Policy-driven firmware patching across the fleet with maintenance windows, canary rings and automatic rollback.', '4Q26', 'pipeline', 'green', 'Code merged. Promotion through pipeline stages underway; verification starts on promotion.', timestamptz '2026-09-22T15:00:00Z' - interval '5 days', '2026-08-21', '2026-09-02', '2026-09-11', '2026-11-14', '2026-12-14'),
  ('CW-1144', 'Hypervisor upgrade wave 3', 'Third and final wave of the hypervisor uplift, covering the remaining regional pools and retiring the legacy control plane.', '4Q26', 'released', 'green', 'GA on 14 Dec 2026. In sustainment; remaining work is defect intake.', timestamptz '2026-09-22T15:00:00Z' - interval '4 days', '2026-08-20', '2026-09-07', '2026-09-12', '2026-11-14', '2026-12-14'),
  ('CW-1150', 'GPU pool scheduler (MIG)', 'Multi-instance GPU partitioning in the shared scheduler so small inference jobs stop reserving whole cards.', '4Q26', 'dev', 'green', 'Build in progress across AI Infra. Dev complete targeted 14 Nov 2026.', timestamptz '2026-09-22T15:00:00Z' - interval '4 days', '2026-08-20', '2026-09-01', '2026-09-12', '2026-11-14', '2026-12-14'),
  ('CW-1158', 'Node lifecycle automation', 'State machine for node intake, burn-in, service, drain and decommission, replacing the runbook-driven process.', '4Q26', 'design', 'green', 'Architecture in review. API spec drafting, merge targeted 2 Sep 2026.', timestamptz '2026-09-22T15:00:00Z' - interval '3 days', '2026-08-19', '2026-09-02', '2026-09-12', '2026-11-14', '2026-12-14'),
  ('CW-1163', 'z/OS 3.2 container runtime', 'Certify and ship the container runtime on z/OS 3.2, including the image registry mirror and admission controls.', '4Q26', 'test', 'red', 'Blocked on the z/OS 3.2 fix pack. Verification cannot start until it lands. In verification. Exit criteria tracking to release on 14 Dec 2026.', timestamptz '2026-09-22T15:00:00Z' - interval '2 days', '2026-08-18', '2026-09-05', '2026-09-13', '2026-11-14', '2026-12-14'),
  ('CW-1171', 'NVMe tiering for Power', 'Automatic hot and cold tiering between NVMe and SAS on Power storage nodes, driven by access telemetry.', '4Q26', 'pipeline', 'green', 'Code merged. Promotion through pipeline stages underway; verification starts on promotion.', timestamptz '2026-09-22T15:00:00Z' - interval '4 days', '2026-08-20', '2026-08-31', '2026-09-13', '2026-11-14', '2026-12-14'),
  ('CW-1180', 'OpenShift on Z 4.19', 'Uplift the OpenShift on Z offering to 4.19 with the new installer flow and operator catalog.', '1Q27', 'design', 'green', 'Architecture in review. API spec drafting, merge targeted 6 Nov 2026.', timestamptz '2026-09-22T15:00:00Z' - interval '7 days', '2026-10-11', '2026-11-06', '2027-02-01', '2027-02-27', '2027-03-22'),
  ('CW-1186', 'Capacity forecasting service', 'Forecast pool capacity 90 days out from booking trends and hardware lead times, surfacing shortfalls to planners.', '1Q27', 'design', 'green', 'Architecture in review. API spec drafting, merge targeted 6 Nov 2026.', timestamptz '2026-09-22T15:00:00Z' - interval '4 days', '2026-10-08', '2026-11-06', '2027-02-01', '2027-02-27', '2027-03-22'),
  ('CW-1192', 'vCenter to KVM migration tooling', 'Assisted migration of VMware estates to the KVM pools: inventory, dependency mapping, conversion and cutover orchestration.', '1Q27', 'requirements', 'green', 'Scoping with stakeholders. Requirements draft in review; SRB submission targeted for 8 Oct 2026.', timestamptz '2026-09-22T15:00:00Z' - interval '4 days', '2026-10-08', '2026-11-10', '2027-02-01', '2027-02-27', '2027-03-22'),
  ('CW-1197', 'Post-quantum TLS across fleet', 'Roll hybrid post-quantum key exchange across control plane and inter-node TLS ahead of the 2027 mandate.', '1Q27', 'design', 'yellow', 'At risk: PQC library selection still unresolved between Security and Network. Architecture in review. API spec drafting, merge targeted 10 Nov 2026.', timestamptz '2026-09-22T15:00:00Z' - interval '9 days', '2026-10-13', '2026-11-10', '2027-02-01', '2027-02-27', '2027-03-22'),
  ('CW-1204', 'Rack-scale telemetry pipeline', 'Replace per-node scrapers with a rack-level collector streaming power, thermal and health data at second granularity.', '1Q27', 'dev', 'green', 'Build in progress across SRE and Network. Dev complete targeted 28 Feb 2027.', timestamptz '2026-09-22T15:00:00Z' - interval '4 days', '2026-10-08', '2026-11-05', '2027-01-25', '2027-02-28', '2027-03-22'),
  ('CW-1210', 'Power11 memory encryption', 'Enable transparent memory encryption on Power11 with per-partition keys and attestation of encrypted state.', '1Q27', 'design', 'green', 'Architecture in review. API spec drafting, merge targeted 9 Nov 2026.', timestamptz '2026-09-22T15:00:00Z' - interval '4 days', '2026-10-08', '2026-11-09', '2027-01-25', '2027-02-28', '2027-03-22'),
  ('CW-1218', 'Zero-touch node onboarding', 'New hardware joins the fleet with no manual steps: DHCP identity, secure boot verification, profile assignment and pool placement.', '1Q27', 'requirements', 'green', 'Scoping with stakeholders. Requirements draft in review; SRB submission targeted for 7 Oct 2026.', timestamptz '2026-09-22T15:00:00Z' - interval '3 days', '2026-10-07', '2026-11-10', '2027-01-26', '2027-02-28', '2027-03-22'),
  ('CW-1223', 'Storage QoS policy engine', 'Per-tenant IOPS and throughput guarantees enforced at the storage fabric, with burst credits and noisy-neighbour isolation.', '1Q27', 'dev', 'green', 'Build in progress across Storage. Dev complete targeted 28 Feb 2027.', timestamptz '2026-09-22T15:00:00Z' - interval '2 days', '2026-10-06', '2026-11-04', '2027-01-26', '2027-02-28', '2027-03-22'),
  ('CW-1229', 'Multi-region failover drills', 'Scheduled, automated failover exercises between regions with measured RTO and RPO and a signed-off report.', '1Q27', 'requirements', 'green', 'Scoping with stakeholders. Requirements draft in review; SRB submission targeted for 12 Oct 2026.', timestamptz '2026-09-22T15:00:00Z' - interval '8 days', '2026-10-12', '2026-11-05', '2027-01-26', '2027-02-28', '2027-03-22'),
  ('CW-1234', 'FedRAMP evidence automation', 'Continuous collection of FedRAMP control evidence from fleet systems, replacing quarterly manual screenshots.', '1Q27', 'design', 'red', 'Blocked awaiting the 3PAO evidence format from Compliance. Architecture in review. API spec drafting, merge targeted 8 Nov 2026.', timestamptz '2026-09-22T15:00:00Z' - interval '7 days', '2026-10-11', '2026-11-08', '2027-01-26', '2027-02-28', '2027-03-22'),
  ('CW-1240', 'Inference serving on LinuxONE', 'Managed inference endpoints on LinuxONE using the on-chip accelerator, with autoscaling and model versioning.', '1Q27', 'requirements', 'green', 'Scoping with stakeholders. Requirements draft in review; SRB submission targeted for 11 Oct 2026.', timestamptz '2026-09-22T15:00:00Z' - interval '7 days', '2026-10-11', '2026-11-02', '2027-01-27', '2027-03-01', '2027-03-22'),
  ('CW-1247', 'Network fabric 800G uplift', 'Upgrade spine and leaf to 800G in the two largest regions and retire the 100G aggregation tier.', '1Q27', 'design', 'green', 'Architecture in review. API spec drafting, merge targeted 3 Nov 2026.', timestamptz '2026-09-22T15:00:00Z' - interval '5 days', '2026-10-09', '2026-11-03', '2027-01-27', '2027-03-01', '2027-03-22'),
  ('CW-1255', 'Kernel live patching rollout', 'Fleet-wide kernel live patching so security fixes land without reboot windows for most CVEs.', '1Q27', 'dev', 'green', 'Build in progress across Kernel and SRE. Dev complete targeted 1 Mar 2027.', timestamptz '2026-09-22T15:00:00Z' - interval '7 days', '2026-10-11', '2026-11-07', '2027-01-27', '2027-03-01', '2027-03-22'),
  ('CW-1262', 'Workload placement advisor', 'Recommend the pool and node class for a workload from its stated profile, learning from observed performance.', '2Q27', 'requirements', 'green', 'Scoping with stakeholders. Requirements draft in review; SRB submission targeted for 15 Mar 2027.', timestamptz '2026-09-22T15:00:00Z' - interval '8 days', '2027-03-15', '2027-04-20', '2027-04-29', '2027-05-31', '2027-06-21'),
  ('CW-1270', 'Sustainability power capping', 'Rack and pool level power caps tied to carbon intensity signals, with workload-aware throttling.', '2Q27', 'requirements', 'green', 'Scoping with stakeholders. Requirements draft in review; SRB submission targeted for 8 Mar 2027.', timestamptz '2026-09-22T15:00:00Z' - interval '1 days', '2027-03-08', '2027-04-15', '2027-04-29', '2027-05-31', '2027-06-21'),
  ('CW-1277', 'Hardware attestation service v2', 'Second-generation attestation covering firmware, boot chain and accelerator identity in a single verifiable report.', '2Q27', 'requirements', 'green', 'Scoping with stakeholders. Requirements draft in review; SRB submission targeted for 15 Mar 2027.', timestamptz '2026-09-22T15:00:00Z' - interval '8 days', '2027-03-15', '2027-04-16', '2027-04-29', '2027-05-31', '2027-06-21'),
  ('CW-1290', 'Firmware SBOM pipeline', 'Generate and publish a software bill of materials for every firmware image at build time and attach it to fleet inventory.', '2Q27', 'design', 'green', 'Architecture in review. API spec drafting, merge targeted 14 Apr 2027.', timestamptz '2026-09-22T15:00:00Z' - interval '9 days', '2027-03-16', '2027-04-14', '2027-04-30', '2027-05-31', '2027-06-21'),
  ('CW-1296', 'Edge compute node profile', 'A hardened, small-footprint node profile for edge sites with intermittent connectivity and remote hands only.', '2Q27', 'requirements', 'green', 'Scoping with stakeholders. Requirements draft in review; SRB submission targeted for 13 Mar 2027.', timestamptz '2026-09-22T15:00:00Z' - interval '6 days', '2027-03-13', '2027-04-14', '2027-04-30', '2027-05-31', '2027-06-21'),
  ('CW-1308', 'Observability cost reduction', 'Cut observability spend by a third through sampling, retention tiers and dropping unused metric series.', '2Q27', 'design', 'green', 'Architecture in review. API spec drafting, merge targeted 19 Apr 2027.', timestamptz '2026-09-22T15:00:00Z' - interval '6 days', '2027-03-13', '2027-04-19', '2027-05-02', '2027-06-01', '2027-06-21'),
  ('CW-1330', 'Cross-cloud burst capacity', 'Burst overflow workloads to partner cloud capacity under a pre-negotiated contract when pools exceed threshold.', '2Q27', 'requirements', 'yellow', 'At risk: cross-cloud egress cost model not yet approved. Scoping with stakeholders. Requirements draft in review; SRB submission targeted for 8 Mar 2027.', timestamptz '2026-09-22T15:00:00Z' - interval '1 days', '2027-03-08', '2027-04-12', '2027-05-03', '2027-06-01', '2027-06-21'),
  ('CW-1283', 'Disaggregated memory pilot', 'Pilot CXL-attached memory pooling on a single rack to measure latency and workload fit.', 'backlog', 'requirements', 'green', 'Scoping with stakeholders. Requirements draft in review; SRB submission targeted for TBD.', timestamptz '2026-09-22T15:00:00Z' - interval '8 days', null, null, null, null, null),
  ('CW-1301', 'Quantum-safe key rotation', 'Rotate long-lived signing and encryption keys to quantum-safe algorithms with dual-signing during transition.', 'backlog', 'requirements', 'green', 'Scoping with stakeholders. Requirements draft in review; SRB submission targeted for TBD.', timestamptz '2026-09-22T15:00:00Z' - interval '8 days', null, null, null, null, null),
  ('CW-1315', 'Container image build farm', 'Shared, cached build farm for container images across teams, with provenance attestations.', 'backlog', 'requirements', 'green', 'Scoping with stakeholders. Requirements draft in review; SRB submission targeted for TBD.', timestamptz '2026-09-22T15:00:00Z' - interval '7 days', null, null, null, null, null),
  ('CW-1322', 'Power savings for idle racks', 'Deep-idle states for racks with no scheduled workload, with wake-up SLAs the scheduler can rely on.', 'backlog', 'requirements', 'green', 'Scoping with stakeholders. Requirements draft in review; SRB submission targeted for TBD.', timestamptz '2026-09-22T15:00:00Z' - interval '8 days', null, null, null, null, null),
  ('CW-1341', 'ARM64 evaluation for edge', 'Evaluate ARM64 nodes for the edge profile against price, performance and the software compatibility matrix.', 'backlog', 'requirements', 'green', 'Scoping with stakeholders. Requirements draft in review; SRB submission targeted for TBD.', timestamptz '2026-09-22T15:00:00Z' - interval '6 days', null, null, null, null, null),
  ('CW-1347', 'Self-service GPU quotas', 'Team-level GPU quotas that owners can adjust within limits without a ticket.', 'backlog', 'requirements', 'green', 'Scoping with stakeholders. Requirements draft in review; SRB submission targeted for TBD.', timestamptz '2026-09-22T15:00:00Z' - interval '3 days', null, null, null, null, null),
  ('CW-1352', 'Fleet-wide secrets rotation', 'Automated rotation of service credentials across the fleet with staged rollout and revocation.', 'backlog', 'requirements', 'green', 'Scoping with stakeholders. Requirements draft in review; SRB submission targeted for TBD.', timestamptz '2026-09-22T15:00:00Z' - interval '2 days', null, null, null, null, null),
  ('CW-1358', 'Object storage cold tier', 'A cold object tier on high-density drives with retrieval SLAs for archive and compliance data.', 'backlog', 'requirements', 'green', 'Scoping with stakeholders. Requirements draft in review; SRB submission targeted for TBD.', timestamptz '2026-09-22T15:00:00Z' - interval '8 days', null, null, null, null, null);

